using System.Text.Json;
using System.Text.Json.Serialization;
using System.Text.Json.Serialization.Metadata;

// Options with the default reflection-based resolver
var options = new JsonSerializerOptions(JsonSerializerDefaults.Web);

// 1️⃣ GetTypeInfo<T>() — returns JsonTypeInfo<T> directly (no cast needed)
JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"GetTypeInfo<Person> → Type = {personInfo.Type.Name}");

string json = JsonSerializer.Serialize(new Person("Ada", 36), personInfo);
Console.WriteLine($"  Serialized: {json}");

// 2️⃣ TryGetTypeInfo<T>() — probe without throwing
if (options.TryGetTypeInfo<Person>(out JsonTypeInfo<Person>? info))
{
    Console.WriteLine($"\nTryGetTypeInfo<Person> → resolved ({info!.Type.Name})");
}

// Now demonstrate the "not available" path using a source-gen context
// that only knows about Person — querying an unknown type returns false.
var strictOptions = new JsonSerializerOptions { TypeInfoResolver = PersonContext.Default };

if (strictOptions.TryGetTypeInfo<UnknownType>(out JsonTypeInfo<UnknownType>? missing))
{
    Console.WriteLine($"\nTryGetTypeInfo<UnknownType> → resolved (unexpected)");
}
else
{
    Console.WriteLine($"\nTryGetTypeInfo<UnknownType> → not available (no exception thrown)");
}

// --- Types -----------------------------------------------------------

public record Person(string Name, int Age);
public record UnknownType(string Value);

[JsonSerializable(typeof(Person))]
public partial class PersonContext : JsonSerializerContext;
EOF

